using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Workshop {
public class WorkshopPlayerProbe:MonoBehaviour {
 static string folder;List<string> lines=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--workshop-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<args.Length?Path.GetFullPath(args[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v4.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var go=new GameObject("Staged workshop verification");DontDestroyOnLoad(go);go.AddComponent<WorkshopPlayerProbe>();}
 void Check(bool yes,string text){lines.Add((yes?"PASS ":"FAIL ")+text);if(!yes){Write();failed=true;Application.Quit(1);throw new Exception(text);}}void Write()=>File.WriteAllLines(Path.Combine(folder,"player-results.txt"),lines);
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string text,string stack,LogType kind){if(!failed&&(kind==LogType.Error||kind==LogType.Exception)){failed=true;lines.Add("FAIL runtime error: "+text);Write();Application.Quit(1);}}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline){Check(false,"Workshop player timed out");}}
 IEnumerator Wait(Func<bool> ready){while(!ready())yield return null;yield return new WaitForSecondsRealtime(.5f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.4f);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();var trial=UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>();for(int i=0;i<70;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(shop.Open(),"Paid Finch expanded workshop opens");yield return Capture("Workshop_Finch_Overview");foreach(var id in new[]{"na_1","gearbox_1","induction_roots_1","cooling_1","cooling_2","brakes_1","brakes_2","brakes_3","tires_1","tires_2","tires_3","intake_1","exhaust_1","exhaust_2","sound_flame_1","sound_flame_2","na_2","na_3","gearbox_2","gearbox_3","induction_roots_2","induction_roots_3"})Check(shop.Install(id),"Paid install "+id);Check(Mathf.Abs(shop.Car.forwardGrip-1.15f*1.2f)<.0001f,"Stage3 tires alter actual longitudinal grip");Check(shop.Car.Engine.definition.aspiration=="supercharged"&&shop.Build.inductionStage==3,"SC staged torque definition actually applied");shop.SelectedId="induction_roots_3";yield return Capture("Workshop_Finch_Supercharged");int money=shop.Credits;Check(!shop.Install("induction_roots_3")&&shop.Credits==money,"Already installed cannot debit again");Check(!shop.Install("induction_twin_1"),"Incompatible Finch twins cannot be purchased");Check(shop.Car.GetComponentsInChildren<AudioSource>().Length==1,"Exactly one engine/effects audio source");Check(shop.Car.GetComponentsInChildren<WheelCollider>().Length==4,"No duplicate wheel physics");shop.Close();shop.Car.externalInput=true;shop.Car.commandedHandbrake=false;shop.Car.commandedPedal=1;yield return new WaitForSecondsRealtime(.4f);Check(shop.Car.GetComponent<WorkshopEffects>().SuperGain>0,"Actual loaded SC produces whine");double revDeadline=Time.realtimeSinceStartupAsDouble+10;while(shop.Car.Engine.Rpm<3200&&Time.realtimeSinceStartupAsDouble<revDeadline)yield return null;Check(shop.Car.Engine.Rpm>=3200,"Actual drive reaches lift-off RPM");shop.Car.commandedPedal=0;yield return new WaitForSecondsRealtime(.18f);Check(shop.Car.GetComponent<WorkshopEffects>().PopCount>0,"Installed flame tune generates a real throttle-lift pop");shop.Car.commandedPedal=0;shop.Car.Recover();shop.Car.externalInput=false;string paid=File.ReadAllText(trial.Store.PathName);Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene),"Return to mode menu");yield return Wait(()=>!HarborValeLaunch.Instance.Busy);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();Check(shop.IsTest&&shop.Build.induction=="none","Apex starts fresh temporary stock build");Check(shop.Open(),"Apex gets same workshop UI");var apex=shop.Catalog;foreach(var step in apex.MissingPath(shop.Build,apex.Find("induction_twin_3")))Check(shop.Install(step.id),"Free Apex stage "+step.id);shop.SelectedId="induction_twin_3";Check(shop.Build.induction=="twin"&&shop.Build.inductionStage==3,"Actual twin-turbo curve installed");yield return Capture("Workshop_Apex_Twins");Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("Workshop_1280x720");Screen.SetResolution(1600,900,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("Workshop_1600x900");shop.Close();Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Free Apex never changes paid Finch ledger");HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();Check(shop.Build.induction=="roots"&&shop.Build.inductionStage==3&&shop.Build.brakeStage==3&&shop.Build.sound=="flame","Paid multistage build reloads after scene roundtrip");Check(!failed,"No native runtime errors");Write();Application.Quit(0);}
}
}
